  ('ARC', 'ARC UK G Ltd', 2, 7.5, 'Flat Rate VAT', '{arc,arc-wise,arc uk g ltd}', null),
  ('YD',  'Youdent Ltd',  3, 0,   null, '{yd,yd-ebay,youdent,youdent ltd,ydent,ebay,yd-wise}', 'Sells as YD-eBay'),
  ('GOE', 'Goenche Ltd',  4, 0,   null, '{goenche,goe}', null),
